    const m = await read($, motion)
    const l = await read($, limits)
    const pr = await read($, prefs)
    const isSetting = await read($, isSettingsOpen)
    const who = await read($, identity)
    const st = await read($, stats)
    const pack = packFor(pr.pack)
    const extras: Extras = {
